    ["bedrock/amazon.nova-canvas-v1:0", "Nova Canvas v1"],
    ["eu.anthropic.claude-3-5-sonnet-20241022-v2:0", "Claude 3.5 Sonnet v2"],
    [
      "accounts/fireworks/models/llama-v3p1-70b-instruct",
