const validDate = (
  year: string,
  month: string,
  day: string | null,
): string | null => {
  const m = Number(month);
  const d = day === null ? 1 : Number(day);
  if (m < 1 || m > 12 || d < 1 || d > 31) return null;
  return day === null ? `${year}-${month}` : `${year}-${month}-${day}`;
};

export function releaseDateFromId(id: string): string | null {
  const iso = ISO_DATE.exec(id);
  if (iso) return validDate(iso[1], iso[2], iso[3]);
  const compact = COMPACT_DATE.exec(id);
  if (compact) return validDate(compact[1], compact[2], compact[3]);
  return null;
}

function normalizeDate(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  const full = FULL_DATE.exec(trimmed);
  if (full) return validDate(full[1], full[2], full[3]);
  const month = MONTH_DATE.exec(trimmed);
  if (month) return validDate(month[1], month[2], null);
  return null;
}

const tailOf = (id: string): string => id.slice(id.lastIndexOf("/") + 1);

const stripDates = (key: string): string =>
  key.replace(ISO_DATE, "").replace(COMPACT_DATE, "").replace(/-+$/, "");

const KEY_STEPS: readonly ((key: string) => string)[] = [
  tailOf,
  (key) => key.replace(FINE_TUNE_PREFIX, ""),
  (key) => key.replace(REGION_PREFIX, ""),
  (key) => key.replace(VENDOR_PREFIX, ""),
  (key) => key.replace(AT_SUFFIX, ""),
  (key) => key.replace(VERSION_SUFFIX, ""),
  stripDates,
];

export function candidateKeys(id: string): readonly Candidate[] {
  const lower = id.toLowerCase();
  const idDate = releaseDateFromId(lower);
  const keys = KEY_STEPS.reduce<readonly { key: string; rank: number }[]>(
    (acc, step, i) => {
      const prev = acc[acc.length - 1].key;
      const next = step(prev);
      return next === prev || next === ""
        ? acc
        : [...acc, { key: next, rank: i + 1 }];
    },
    [{ key: lower, rank: 0 }],
  );
  return keys.map(({ key, rank }) => ({
    key,
    rank,
    dateStripped: idDate !== null && releaseDateFromId(key) === null,
  }));
}

const VENDOR_NAME_PREFIX = /^[A-Za-z0-9 .]+: /;

const ID_LIKE_NAME = /^[^\s]*[-_.\d][^\s]*$/;

const isRawName = (name: string, modelId: string): boolean =>
  ID_LIKE_NAME.test(name) && modelId.toLowerCase().includes(name.toLowerCase());

export function buildModelsDevIndex(api: ModelsDevApi): ModelsDevIndex {
  const entries = Object.entries(api).flatMap(([provider, { models }]) =>
    Object.entries(models ?? {}).flatMap(([modelId, model]) => {
      const name =
        typeof model.name === "string"
          ? model.name.trim().replace(VENDOR_NAME_PREFIX, "")
          : "";
      if (name === "") return [];
      const date = normalizeDate(model.release_date);
      const raw = isRawName(name, modelId);
      return candidateKeys(modelId).map(
        ({ key, rank }) => [key, { rank, name, date, provider, raw }] as const,
      );
    }),
  );
  return entries.reduce(
    (index, [key, entry]) => index.set(key, [...(index.get(key) ?? []), entry]),
    new Map<string, readonly IndexedEntry[]>(),
  );
}

function mode(values: readonly string[]): string | null {
  const counts = values.reduce(
    (acc, value) => acc.set(value, (acc.get(value) ?? 0) + 1),
    new Map<string, number>(),
  );
  const best = [...counts.entries()].reduce<readonly [string, number] | null>(
    (winner, current) =>
      winner === null || current[1] > winner[1] ? current : winner,
    null,
  );
  return best === null ? null : best[0];
}

const SOURCE_POOLS: readonly ((entry: IndexedEntry) => boolean)[] = [
  (entry) => FIRST_PARTY_PROVIDERS.has(entry.provider),
  (entry) => !entry.raw,
  () => true,
];

function pickHit(
  entries: readonly IndexedEntry[],
  dateStripped: boolean,
): Hit | null {
  const bestRank = Math.min(...entries.map((entry) => entry.rank));
  const bucket = entries.filter((entry) => entry.rank === bestRank);
  const name = mode(bucket.map((entry) => entry.name));
  if (name === null) return null;
  const raw = bucket
    .filter((entry) => entry.name === name)
    .every((entry) => entry.raw);
  const dates = bucket
    .map((entry) => entry.date)
    .filter((date): date is string => date !== null);
  const date =
    mode(dates.filter((date) => FULL_DATE.test(date))) ?? mode(dates);
  return { name, raw, date, dateStripped };
}

function lookupModelsDev(index: ModelsDevIndex, id: string): Hit | null {
  const candidates = candidateKeys(id);
  for (const inPool of SOURCE_POOLS) {
    for (const candidate of candidates) {
      const entries = (index.get(candidate.key) ?? []).filter(inPool);
      if (entries.length === 0) continue;
      const hit = pickHit(entries, candidate.dateStripped);
      if (hit !== null) return hit;
    }
  }
  return null;
}

function formatToken(token: string): string {
  const acronym = ACRONYMS.get(token);
  if (acronym !== undefined) return acronym;
  if (SIZED_TOKEN.test(token)) {
    return token
      .replace(/[bkm]$/, (unit) => unit.toUpperCase())
      .replace(/^[a-z]/, (c) => c.toUpperCase());
  }
  if (/^o\d/.test(token) || /^v\d/.test(token) || /^\d/.test(token))
    return token;
  return token.charAt(0).toUpperCase() + token.slice(1);
}

function joinTokens(tokens: readonly string[]): string {
  return tokens.reduce((out, token, i) => {
    if (i === 0) return token;
    const prev = tokens[i - 1];
    const separator =
      HYPHENATED_ACRONYMS.has(prev) && /^\d/.test(token)
        ? "-"
        : /^\d$/.test(prev) && /^\d{1,2}$/.test(token)
          ? "."
          : " ";
    return out + separator + token;
  }, "");
}

export function humanizeModelId(id: string): string {
  const base = tailOf(id)
    .toLowerCase()
    .replace(FINE_TUNE_PREFIX, "")
    .replace(REGION_PREFIX, "")
    .replace(VENDOR_PREFIX, "")
    .replace(AT_SUFFIX, "")
    .replace(VERSION_TAG_SUFFIX, "");
  const tokens = stripDates(base)
    .replace(/dall-e/g, "dall·e")
    .split(/[-_]+/)
    .filter((token) => token !== "")
    .map(formatToken);
  return joinTokens(tokens);
}

function qualifiers(id: string): readonly string[] {
  return id
    .split("/")
    .slice(0, -1)
    .flatMap((segment) => {
      const size = SIZE_QUALIFIER.exec(segment);
      if (size) return [`${size[1]}×${size[2]}`];
      const steps = STEPS_QUALIFIER.exec(segment);
      if (steps) return [`${steps[1]} steps`];
      return [];
    });
}

function regionLabel(id: string): string | null {
  const match = REGION_PREFIX.exec(
    tailOf(id).toLowerCase().replace(FINE_TUNE_PREFIX, ""),
  );
  return match === null
    ? null
    : REGION_LABELS[match[1]] ?? match[1].toUpperCase();
}

function decorateName(name: string, id: string): string {
  const prefixed = FINE_TUNE_PREFIX.test(tailOf(id))
    ? `Fine-tuned ${name}`
    : name;
  const region = regionLabel(id);
  const regional = region === null ? prefixed : `${prefixed} (${region})`;
  const extras = qualifiers(id);
  return extras.length === 0 ? regional : `${regional} · ${extras.join(", ")}`;
}

export function deriveModelMeta(id: string, index: ModelsDevIndex): ModelMeta {
  const idDate = releaseDateFromId(id);
  const hit = lookupModelsDev(index, id);
  const baseName =
    hit === null || hit.raw
      ? humanizeModelId(id)
      : hit.name.replace(REGION_NAME_SUFFIX, "");
  const release_date =
    hit === null || hit.dateStripped
      ? idDate ?? hit?.date ?? null
      : hit.date ?? idDate;
  return { display_name: decorateName(baseName, id), release_date };
}

export function compareReleaseDates(
  a: string | null,
  b: string | null,
  direction: "asc" | "desc",
): number {
  if (a === null && b === null) return 0;
  if (a === null) return 1;
  if (b === null) return -1;
  const order = a < b ? -1 : a > b ? 1 : 0;
  return direction === "asc" ? order : -order;
}

export function formatReleaseMonth(date: string | null): string {
  if (date === null) return "—";
  return `${MONTHS[Number(date.slice(5, 7)) - 1]} ${date.slice(0, 4)}`;
}

export function formatReleaseDate(date: string | null): string {
  if (date === null) return "—";
  if (date.length !== 10) return formatReleaseMonth(date);
  return `${MONTHS[Number(date.slice(5, 7)) - 1]} ${Number(date.slice(8, 10))}, ${date.slice(0, 4)}`;
}

export const MODELS_DEV_TIMEOUT_MS = 10_000;

export function loadModelsDevIndex(
  fetchImpl: typeof fetch,
  timeoutMs: number,
): Promise<ModelsDevIndex> {
  const abort = new AbortController();
  const timer = setTimeout(() => abort.abort(), timeoutMs);
  return fetchImpl(MODELS_DEV_API_URL, { signal: abort.signal })
    .then((res) =>
      res.ok
        ? res.json()
        : Promise.reject(new Error(`models.dev responded ${res.status}`)),
    )
    .then((api: ModelsDevApi) => buildModelsDevIndex(api))
    .catch((err: unknown) => {
      console.error("models.dev metadata unavailable", err);
      return EMPTY_MODELS_DEV_INDEX;
    })
    .finally(() => clearTimeout(timer));
}

/**
 * Load models from litellm-model-catalog-api (paginated) and map to the
 * flat item shape the UI expects (name + litellm_provider).
 */

export type PricingSlot = {
  amount_usd: number | null;
  unit: string | null;
  source_field: string | null;
};

export type PricingSlots = {
  input: PricingSlot;
  output: PricingSlot;
  cache_read: PricingSlot;
  cache_write: PricingSlot;
};

export type CatalogApiEntry = {
  id: string;
  provider?: string | null;
  pricing_slots?: PricingSlots;
  [key: string]: unknown;
};

function isRecord(v: unknown): v is Record<string, unknown> {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}

function toAmountUsd(amount: unknown): number | null {
  // Only accept finite numbers and non-empty numeric strings. An empty or
  // whitespace-only string must stay null so it falls back to legacy fields,
  // matching num() in modelPresentation.ts (Number("") would coerce to 0).
  if (typeof amount === "number") return Number.isFinite(amount) ? amount : null;
  if (typeof amount === "string") {
    const trimmed = amount.trim();
    if (trimmed === "") return null;
    const parsed = Number(trimmed);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

function asPricingSlot(v: unknown): PricingSlot {
  if (!isRecord(v)) return { amount_usd: null, unit: null, source_field: null };
  return {
    amount_usd: toAmountUsd(v.amount_usd),
    unit: typeof v.unit === "string" ? v.unit : null,
    source_field: typeof v.source_field === "string" ? v.source_field : null,
  };
}

export function normalizePricingSlots(raw: unknown): PricingSlots | undefined {
  if (!isRecord(raw)) return undefined;
  return {
    input: asPricingSlot(raw.input),
    output: asPricingSlot(raw.output),
    cache_read: asPricingSlot(raw.cache_read),
    cache_write: asPricingSlot(raw.cache_write),
  };
}

/** Map one API catalog row to UI item (GitHub JSON shape + pricing_slots). */
export function mapCatalogEntryToItem(entry: CatalogApiEntry): Record<string, unknown> {
  const { id, provider, pricing_slots, object: _object, ...rest } = entry;
  const slots = normalizePricingSlots(pricing_slots);
  return {
    ...rest,
    name: id,
    litellm_provider: (provider as string) ?? (rest.litellm_provider as string) ?? "",
    pricing_slots: slots,
  };
}

/** Format a USD amount exactly as in the catalog — no "<$0.01" floors. */
export function formatExactUsd(n: number, suffix = ""): string {
  if (Number.isNaN(n)) return "—";
  if (n === 0) return "$0.00" + suffix;
  const abs = Math.abs(n);
  const decimals = abs >= 0.01 ? 2 : 10;
  let s = n.toFixed(decimals);
  if (abs < 0.01) {
    s = s.replace(/\.?0+$/, "");
  }
  return "$" + s + suffix;
}

/** Per-token catalog field → exact per-1M-token display. */
export function formatTokenCostPerMillion(perToken: number | null | undefined): string {
  if (perToken === null || perToken === undefined) return "—";
  return formatExactUsd(perToken * 1e6, "/M");
}

export function formatPricingSlot(slot: PricingSlot | undefined): string {
  if (!slot || slot.amount_usd == null || Number.isNaN(slot.amount_usd)) return "—";
  const u = slot.unit ?? "";
  const n = slot.amount_usd;
  if (u === "per_1m_tokens" || u === "per_1m_reasoning_tokens" || u === "per_1m_image_tokens" || u === "per_1m_audio_tokens") {
    return formatExactUsd(n, "/M");
  }
  if (u === "per_image") {
    return formatExactUsd(n, "/img");
  }
  if (u === "per_pixel") {
    return formatExactUsd(n * 1e6, "/Mpx");
  }
  if (u === "per_character") {
    return formatExactUsd(n, "/char");
  }
  if (u === "per_query") {
    return formatExactUsd(n, "/q");
  }
  if (u === "per_request") {
    return formatExactUsd(n, "/req");
  }
  if (u === "per_second" || u === "per_second_video") {
    return formatExactUsd(n, "/s");
  }
  return formatExactUsd(n);
}

export function slotSortValue(slot: PricingSlot | undefined): number {
  if (!slot || slot.amount_usd == null || Number.isNaN(slot.amount_usd)) return 0;
  return slot.amount_usd;
}

export type CatalogFetchResult = {
  models: Record<string, unknown>[];
  /** Present when the API returns it (page 1 of list); schema reference from source JSON. */
  sample_spec: Record<string, unknown> | null;
};

/**
 * Fetch every page from GET /model_catalog (max page_size 500).
 * `baseUrl` should have no trailing slash, e.g. "" for same-origin proxy or "http://127.0.0.1:8000".
 */
export async function fetchAllCatalogModels(baseUrl: string): Promise<CatalogFetchResult> {
  const root = baseUrl.replace(/\/$/, "");
  const all: Record<string, unknown>[] = [];
  let sample_spec: Record<string, unknown> | null = null;
  let page = 1;
  let hasMore = true;
  while (hasMore) {
    const path = `/model_catalog?page=${page}&page_size=500`;
    const url = root ? `${root}${path}` : path;
    const res = await fetch(url);
    if (!res.ok) {
      throw new Error(`Catalog API ${res.status}: ${await res.text()}`);
    }
    const json = (await res.json()) as {
      data?: CatalogApiEntry[];
      has_more?: boolean;
      sample_spec?: Record<string, unknown> | null;
    };
    if (page === 1 && json.sample_spec != null && typeof json.sample_spec === "object" && !Array.isArray(json.sample_spec)) {
      sample_spec = json.sample_spec;
    }
    const batch = json.data ?? [];
    for (const row of batch) {
      if (row?.id === "sample_spec") continue;
      all.push(mapCatalogEntryToItem(row));
    }
    hasMore = Boolean(json.has_more);
    page += 1;
    if (hasMore && page > 200) {
      // Safety cap: surface an error instead of silently returning a partial
      // catalog so callers can show loadError rather than a truncated list.
      throw new Error(
        `Catalog API returned more than 200 pages with has_more=true; aborting to avoid silent truncation`,
      );
    }
  }
  return { models: all, sample_spec };
}

