function qualifierFor(m: Member): string {
  const f = m.flags;
  const parts: string[] = [];
  if (f.geoProfile) parts.push(GEO_LABELS[f.geoProfile] ?? f.geoProfile);
  if (f.region) parts.push(f.region);
  if (f.commitment) parts.push(f.commitment.replace(/-/g, " "));
  if (f.imageSize) parts.push(f.imageSize.replace("-x-", "×"));
  if (f.quality) parts.push(`${f.quality} quality`);
  if (f.steps) parts.push(f.steps.replace("-", " "));
  if (f.tag) parts.push(f.tag);
  if (f.quant) parts.push(f.quant);
  if (f.fineTune) parts.push("fine-tuned");
  if (f.routerAlias) parts.push("router alias");
  if (f.snapshot) parts.push(`snapshot ${f.snapshot}`);
  if (f.latestAlias) parts.push("latest alias");
  return parts.join(", ");
}

function isStandard(m: Member): boolean {
  const f = m.flags;
  return !(
    f.geoProfile ||
    f.region ||
    f.commitment ||
    f.imageSize ||
    f.quality ||
    f.steps ||
    f.tag ||
    f.quant ||
    f.fineTune ||
    f.routerAlias
  );
}

/** Same rule the catalog table uses for the copyable model name. */
export function modelString(key: string, provider: string): string {
  if (!key.includes("/") && provider.startsWith("vertex_ai")) return `vertex_ai/${key}`;
  return key;
}

function intOf(v: unknown): number | undefined {
  return typeof v === "number" && Number.isFinite(v) && v > 0 ? v : undefined;
}

function median(values: number[]): number {
  const s = [...values].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

/** Rows priced 8x above or below the group median are likely data errors; keep them out of headlines. */
function flagOutliers(rows: RowView[]): void {
  const byUnit = new Map<string, RowView[]>();
  for (const r of rows) {
    if (!r.metric || r.metric.value <= 0) continue;
    const list = byUnit.get(r.metric.unit) ?? [];
    list.push(r);
    byUnit.set(r.metric.unit, list);
  }
  for (const list of byUnit.values()) {
    if (list.length < 3) continue;
    const m = median(list.map((r) => r.metric!.value));
    for (const r of list) if (r.metric!.value > m * 8 || r.metric!.value < m / 8) r.outlier = true;
  }
}

function dominantMode(members: Member[]): string {
  const counts = new Map<string, number>();
  for (const m of members) counts.set(m.mode, (counts.get(m.mode) ?? 0) + (FIRST_PARTY_PROVIDERS.has(m.provider) ? 3 : 1));
  return [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0][0];
}

function pickHeadline(rows: RowView[]): { row: RowView | null; basis: ModelView["headlineBasis"] } {
  const clean = rows.filter((r) => r.metric && !r.outlier);
  const standard = clean.filter((r) => r.standard);
  const firstParty = standard.filter((r) => r.firstParty);
  if (firstParty.length) {
    const order = (r: RowView) => {
      const i = FIRST_PARTY_ORDER.indexOf(r.provider);
      return i === -1 ? FIRST_PARTY_ORDER.length : i;
    };
    const undated = (r: RowView) => (/snapshot|latest/.test(r.qualifier) ? 1 : 0);
    const best = [...firstParty].sort(
      (a, b) => undated(a) - undated(b) || order(a) - order(b) || a.key.length - b.key.length || a.key.localeCompare(b.key),
    )[0];
    return { row: best, basis: "first_party" };
  }
  const pool = standard.length ? standard : clean;
  if (!pool.length) return { row: null, basis: "only" };
  const cheapest = [...pool].sort(
    (a, b) => a.metric!.value - b.metric!.value || a.key.length - b.key.length || a.key.localeCompare(b.key),
  )[0];
  const providers = new Set(pool.map((r) => r.providerName));
  return { row: cheapest, basis: providers.size > 1 ? "lowest" : "only" };
}

/** Tidy a name built from a model id: drop region and size qualifiers, "v4" -> "V4", trailing "03 2025" dates. */
export function cleanName(name: string): string {
  return name
    .replace(/\s\((US|EU|APAC|Global|JP|AU|CA|IN|US-GOV)\)$/i, "")
    .replace(/\s·\s.*$/, "")
    .replace(/\bv(\d)/g, "V$1")
    .replace(/\s(0[1-9]|1[0-2])\s20\d{2}$/, "")
    .trim();
}

export function buildModelView(
  group: Group,
  slug: string,
  overrides: Overrides,
  support: ProviderSupport,
  addedDate: string | null,
  /** Build date; an introductory price is dropped once it has ended. */
  today?: string,
): ModelView {
  const mode = dominantMode(group.members);
  const lab = labFor(slug, group.members.map((m) => m.vendor));
  const memberKeys = new Set(group.members.map((m) => m.key));
  const isShadowedByPrefixedTwin = (m: Member) => {
    const callName = modelString(m.key, m.provider);
    return callName !== m.key && memberKeys.has(callName);
  };
  const rows: RowView[] = group.members.filter((m) => !isShadowedByPrefixedTwin(m)).map((m) => {
    const prices = rowPrices(m.row);
    const deprecation = typeof m.row.deprecation_date === "string" ? m.row.deprecation_date : undefined;
    const source = typeof m.row.source === "string" && m.row.source.startsWith("http") ? m.row.source : undefined;
    return {
      key: m.key,
      provider: m.provider,
      providerName: providerName(m.provider, support),
      hub: hubProvider(m.provider),
      qualifier: qualifierFor(m),
      modelString: modelString(m.key, m.provider),
      mode: m.mode,
      prices,
      metric: primaryMetric(m.mode, prices),
      outlier: false,
      firstParty: FIRST_PARTY_PROVIDERS.has(m.provider) && isLabProvider(m.provider, lab),
      standard: isStandard(m),
      fineTuned: Boolean(m.flags.fineTune),
      context: intOf(m.row.max_input_tokens) ?? intOf(m.row.max_tokens),
      maxOutput: intOf(m.row.max_output_tokens),
      deprecation,
      source,
    };
  });
  flagOutliers(rows);
  const { row: headline, basis } = pickHeadline(rows);

  // Headline first, then the lab's own rows, then providers alphabetically.
  rows.sort((a, b) => {
    if (a === headline) return -1;
    if (b === headline) return 1;
    return (
      Number(b.firstParty) - Number(a.firstParty) ||
      Number(b.standard) - Number(a.standard) ||
      a.providerName.localeCompare(b.providerName) ||
      a.key.localeCompare(b.key)
    );
  });

  // Names come from LiteLLM's own model ids (plus overrides.json), never from outside sources.
  const nameMember = group.members.find((m) => m.key === headline?.key) ?? group.members.find(isStandard) ?? group.members[0];
  const name = overrides.displayNames?.[group.pageKey] ?? cleanName(deriveModelMeta(nameMember.displayId, EMPTY_MODELS_DEV_INDEX).display_name);

  const providers: ModelView["providers"] = [];
  for (const r of rows) {
    if (!providers.some((p) => p.name === r.providerName)) providers.push({ name: r.providerName, hub: r.hub });
  }

  const capRow = headline ? group.members.find((m) => m.key === headline.key)!.row : group.members[0].row;
  const capabilities: Capability[] = [];
  for (const [field, label] of CAPABILITIES) {
    const own = capRow[field];
    const value = typeof own === "boolean" ? own : group.members.some((m) => m.row[field] === true) ? true : undefined;
    if (value !== undefined) capabilities.push({ label, supported: value });
  }
  const strings = (v: unknown) => (Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : []);

  // The prose quotes this range, so it comes from the same rows the table renders (regional and
  // GovCloud rows included). Flagged outliers and fine-tuned models, a product of their own, stay out,
  // and the table marks both.
  const priced = rows.filter((r) => r.metric && !r.outlier && !r.fineTuned && r.metric.unit === headline?.metric?.unit);
  let range: ModelView["range"];
  if (new Set(priced.map((r) => r.providerName)).size > 1) {
    const sorted = [...priced].sort((a, b) => a.metric!.value - b.metric!.value);
    range = {
      min: sorted[0].metric!.value,
      max: sorted[sorted.length - 1].metric!.value,
      minProvider: sorted[0].providerName,
    };
  }

  const sources = [...new Set(rows.filter((r) => r.source).sort((a, b) => Number(b.firstParty) - Number(a.firstParty)).map((r) => r.source!))].slice(0, 4);
  const docs: ModelView["docs"] = [];
  for (const p of providers) {
    const url = providerDocsUrl(p.hub, support);
    if (url && !docs.some((d) => d.url === url)) docs.push({ name: p.name, url });
  }

  const introEntry = overrides.introPricing?.[group.pageKey];
  // The note describes one seller's price: show it only when the headline comes from that seller.
  const introSeller = headline && (introEntry?.providers ? introEntry.providers.includes(headline.provider) : headline.firstParty);
  const intro = introEntry && introSeller && (!today || introEntry.until >= today) ? introEntry : undefined;

  // Free only when nothing on the headline row costs money: Lyria has $0 tokens but charges per clip.
  const free =
    !!headline &&
    (CHAT_MODES.has(mode) || mode === "embedding") &&
    !Object.values(headline.prices).some((x) => typeof x === "number" && x > 0);

  return {
    pageKey: group.pageKey,
    slug,
    name,
    alsoKnownAs: overrides.alsoKnownAs?.[group.pageKey] ?? [],
    lab,
    mode,
    rows,
    headline,
    headlineBasis: basis,
    providers,
    context: headline?.context ?? rows.find((r) => r.context)?.context,
    maxOutput: headline?.maxOutput ?? rows.find((r) => r.maxOutput)?.maxOutput,
    addedDate,
    deprecation: headline?.deprecation,
    status: overrides.status?.[group.pageKey] ?? modelStatus(rows, headline, today),
    intro,
    capabilities,
    inputModalities: strings(capRow.supported_modalities),
    outputModalities: strings(capRow.supported_output_modalities),
    sources,
    docs: docs.slice(0, 6),
    range,
    free,
  };
}

export function isImageMode(mode: string): boolean {
  return IMAGE_MODES.has(mode);
}

/**
 * Turns one cost-map row into display prices. Token prices are per 1M tokens,
 * the unit every pricing page and search snippet uses.
 */
import type { CostRow } from "./group";

export type LongContextTier = { above: number; input?: number; output?: number; cacheRead?: number };

export type RowPrices = {
  input?: number;
  output?: number;
  cacheRead?: number;
  cacheWrite?: number;
  cacheWrite1h?: number;
  batchInput?: number;
  batchOutput?: number;
  priorityInput?: number;
  priorityOutput?: number;
  flexInput?: number;
  flexOutput?: number;
  longContext: LongContextTier[];
  perImage?: number;
  inputPerImage?: number;
  imageOutputTokens?: number;
  perMegapixel?: number;
  perSecond?: number;
  perMinute?: number;
  per1MChars?: number;
  audioInput?: number;
  audioOutput?: number;
  searchPer1K?: number;
  queryPer1K?: number;
  pagePer1K?: number;
};

export type MetricUnit =
  | "per_1m_tokens"
  | "per_image"
  /** `output_cost_per_image` on a model that doesn't make images, such as Lyria's music clips. */
  | "per_output"
  | "per_megapixel"
  | "per_second"
  | "per_minute"
  | "per_1m_chars"
  | "per_1k_queries"
  | "per_1k_pages";

export type Metric = { value: number; unit: MetricUnit };

export const UNIT_LABEL: Record<MetricUnit, string> = {
  per_1m_tokens: "per 1M tokens",
  per_image: "per image",
  per_output: "per generation",
  per_megapixel: "per megapixel",
  per_second: "per second",
  per_minute: "per minute",
  per_1m_chars: "per 1M characters",
  per_1k_queries: "per 1K queries",
  per_1k_pages: "per 1K pages",
};

export const CHAT_MODES = new Set(["chat", "responses", "completion", "realtime", "moderation"]);
export const IMAGE_MODES = new Set(["image_generation", "image_edit"]);

function num(v: unknown): number | undefined {
  if (typeof v === "number" && Number.isFinite(v) && v >= 0) return v;
  if (typeof v === "string" && v.trim() !== "") {
    const n = Number(v);
    return Number.isFinite(n) && n >= 0 ? n : undefined;
  }
  return undefined;
}

const perM = (v: unknown) => {
  const n = num(v);
  return n === undefined ? undefined : n * 1e6;
};
const times = (v: unknown, k: number) => {
  const n = num(v);
  return n === undefined ? undefined : n * k;
};

const LONG_CONTEXT = /^input_cost_per_token_above_(\d+)k_tokens$/;

export function rowPrices(row: CostRow): RowPrices {
  const longContext: LongContextTier[] = [];
  for (const field of Object.keys(row)) {
    const m = LONG_CONTEXT.exec(field);
    if (!m) continue;
    const k = m[1];
    longContext.push({
      above: Number(k) * 1000,
      input: perM(row[field]),
      output: perM(row[`output_cost_per_token_above_${k}k_tokens`]),
      cacheRead: perM(row[`cache_read_input_token_cost_above_${k}k_tokens`]),
    });
  }
  longContext.sort((a, b) => a.above - b.above);

  const search = row.search_context_cost_per_query;
  const searchMedium =
    search && typeof search === "object"
      ? num((search as Record<string, unknown>).search_context_size_medium)
      : undefined;

  return {
    input: perM(row.input_cost_per_token),
    output: perM(row.output_cost_per_token),
    cacheRead: perM(row.cache_read_input_token_cost),
    cacheWrite: perM(row.cache_creation_input_token_cost),
    cacheWrite1h: perM(row.cache_creation_input_token_cost_above_1hr),
    batchInput: perM(row.input_cost_per_token_batches),
    batchOutput: perM(row.output_cost_per_token_batches),
    priorityInput: perM(row.input_cost_per_token_priority),
    priorityOutput: perM(row.output_cost_per_token_priority),
    flexInput: perM(row.input_cost_per_token_flex),
    flexOutput: perM(row.output_cost_per_token_flex),
    longContext,
    perImage: num(row.output_cost_per_image),
    inputPerImage: num(row.input_cost_per_image),
    imageOutputTokens: perM(row.output_cost_per_image_token),
    perMegapixel: perM(row.output_cost_per_pixel),
    perSecond: num(row.output_cost_per_second) ?? num(row.cost_per_second),
    perMinute: times(row.input_cost_per_second, 60),
    per1MChars: perM(row.input_cost_per_character),
    audioInput: perM(row.input_cost_per_audio_token),
    audioOutput: perM(row.output_cost_per_audio_token),
    searchPer1K: searchMedium === undefined ? undefined : searchMedium * 1000,
    queryPer1K: times(row.input_cost_per_query, 1000),
    pagePer1K: times(row.ocr_cost_per_page, 1000),
  };
}

/** The one number that best answers "how much does this model cost" for its mode. */
export function primaryMetric(mode: string, p: RowPrices): Metric | null {
  // A $0 price gives way only to a paid one in another unit: Lyria lists $0 tokens next to its real per-clip
  // price, while a $0 input price with paid output stays the $0 input price the table shows.
  const pick = (...candidates: [number | undefined, MetricUnit][]): Metric | null => {
    const defined = candidates.flatMap(([value, unit]) => (value === undefined ? [] : [{ value, unit }]));
    const first = defined[0];
    if (!first || first.value > 0) return first ?? null;
    return defined.find((m) => m.value > 0 && m.unit !== first.unit) ?? first;
  };
  if (IMAGE_MODES.has(mode)) {
    return pick(
      [p.perImage, "per_image"],
      [p.imageOutputTokens, "per_1m_tokens"],
      [p.perMegapixel, "per_megapixel"],
      [p.output, "per_1m_tokens"],
      [p.input, "per_1m_tokens"],
    );
  }
  if (mode === "video_generation") return pick([p.perSecond, "per_second"], [p.perImage, "per_image"]);
  if (mode === "audio_speech") {
    return pick([p.per1MChars, "per_1m_chars"], [p.perSecond, "per_second"], [p.output, "per_1m_tokens"], [p.perImage, "per_output"]);
  }
  if (mode === "audio_transcription") {
    return pick([p.perMinute, "per_minute"], [p.input, "per_1m_tokens"], [p.audioInput, "per_1m_tokens"]);
  }
  if (mode === "rerank") return pick([p.queryPer1K, "per_1k_queries"], [p.input, "per_1m_tokens"]);
  if (mode === "ocr") return pick([p.pagePer1K, "per_1k_pages"], [p.input, "per_1m_tokens"]);
  return pick(
    [p.input, "per_1m_tokens"],
    [p.output, "per_1m_tokens"],
    [p.perImage, "per_output"],
    [p.perSecond, "per_second"],
  );
}

/** Whether a row's headline is its token prices, rather than a per-output price on a $0-token row. */
export function leadsWithTokens(mode: string, p: RowPrices, metric: Metric | null | undefined): boolean {
  return CHAT_MODES.has(mode) && p.input !== undefined && p.output !== undefined && metric?.unit === "per_1m_tokens";
}

export function isTokenPriced(mode: string): boolean {
  return CHAT_MODES.has(mode) || mode === "embedding";
}

import { describe, expect, test } from "vitest";
import { CALC_DEFAULTS, CALC_JS, calcCost, calcMoney } from "./calculator";
import { calcSection } from "./html";
import { assignSlugs, groupCostMap } from "./group";
import { buildModelView } from "./model-view";

const view = (input: number, output: number, mode = "chat") => {
  const groups = groupCostMap({
    "claude-opus-5-5": {
      litellm_provider: "anthropic",
      mode,
      input_cost_per_token: input / 1e6,
      output_cost_per_token: output / 1e6,
      max_input_tokens: 1_000_000,
    },
  });
  const slugs = assignSlugs(groups);
  return buildModelView(
    groups[0],
    slugs.get(groups[0].pageKey)!,
    {},
    {},
    null,
    "2026-10-20",
  );
};

describe("cost calculator", () => {
  test("renders the default workload's result in the HTML, so crawlers see a number", () => {
    const html = calcSection(view(4, 20));
    expect(CALC_DEFAULTS).toEqual({
      input: 1000,
      output: 500,
      requests: 10_000,
    });
    expect(html).toContain('<dd data-r="req">$0.014</dd>');
    expect(html).toContain('<dd data-r="day">$140</dd>');
    expect(html).toContain('<dd data-r="month">$4,200</dd>');
    expect(html).toContain("cost $140 a day, about $4,200 a month");
  });

  test("is left off models that aren't priced per input and output token", () => {
    expect(calcSection(view(0, 0))).toBe("");
  });

  test("the page script formats money exactly like the build", () => {
    const src = /var fmt=(function\(n\)\{[^}]*\})/.exec(CALC_JS)![1];
    const fmt = new Function(`return ${src}`)() as (n: number) => string;
    for (const n of [
      0, 0.000115, 0.007, 0.0175, 0.7, 1, 3.5, 99.99, 100, 4200, 123456.7,
    ])
      expect(fmt(n)).toBe(calcMoney(n));
    expect(calcMoney(0.7)).toBe("$0.70");
  });

  test("a cost that is a half cent up to float noise rounds up in the build and the page script", () => {
    const { perDay } = calcCost(0.025, 0.025, 1000, 500, 10_000);
    const src = /var fmt=(function\(n\)\{[^}]*\})/.exec(CALC_JS)![1];
    const fmt = new Function(`return ${src}`)() as (n: number) => string;
    expect(calcMoney(perDay)).toBe("$0.38");
    expect(fmt(perDay)).toBe("$0.38");
  });

  test("arithmetic: (in × input price + out × output price) per request, × requests, × 30 days", () => {
    expect(calcCost(4, 20, 2000, 500, 10_000)).toEqual({
      perRequest: 0.018,
      perDay: 180,
      perMonth: 5400,
    });
  });
});

// @vitest-environment happy-dom
import { afterEach, describe, expect, test, vi } from "vitest";
import { CALCULATOR_PAGE_JS } from "./calculator";
import { TOOL_JS, toolBody } from "./compare-tool";
import { calculatorBody, type CalcModel } from "./html";

const run = (script: string) =>
  new Function(script.replace(/^<script>|<\/script>$/g, ""))();

const key = (el: Element, k: string) =>
  el.dispatchEvent(new KeyboardEvent("keydown", { key: k, bubbles: true }));

const type = (el: HTMLInputElement, text: string) => {
  el.value = text;
  el.dispatchEvent(new Event("input", { bubbles: true }));
};

const model = (slug: string, name: string, intro?: string): CalcModel => ({
  slug,
  name,
  input: 1,
  output: 2,
  providers: 1,
  ...(intro ? { intro } : {}),
});

const MODELS = [
  model("gpt-oss-120b", "GPT OSS 120B"),
  model("gpt-5-5", "GPT-5.5"),
  model("gpt-5", "GPT-5"),
  model("claude-opus-5-5", "Claude Opus 5.5"),
  model("gemini-4-argon", "Gemini 4 Argon", "November 30, 2026"),
];

afterEach(() => {
  document.body.innerHTML = "";
  vi.unstubAllGlobals();
});

describe("calculator model picker", () => {
  const open = (search = "") => {
    history.replaceState(null, "", `/calculator${search}`);
    document.body.innerHTML = calculatorBody(
      MODELS,
      "claude-opus-5-5",
      [],
      "2026-10-20",
    );
    run(CALCULATOR_PAGE_JS);
    const box = document.querySelector<HTMLInputElement>(".calc-pick")!;
    box.dispatchEvent(new Event("focus"));
    return box;
  };
  const picked = () =>
    document.querySelector<HTMLInputElement>('[name="model"]')!.value;
  const introNote = () =>
    document.querySelector<HTMLElement>("[data-r=intro]")!;

  test("an exact name is picked before longer names that contain it", () => {
    const box = open();
    type(box, "gpt-5");
    key(box, "Enter");
    expect(picked()).toBe("gpt-5");
  });

  test("spaces around the search still match, as in the comparison picker", () => {
    const box = open();
    type(box, " gpt-5 ");
    key(box, "Enter");
    expect(picked()).toBe("gpt-5");
  });

  test("Enter on a freshly opened list keeps the current model", () => {
    const box = open();
    key(box, "Enter");
    expect(picked()).toBe("claude-opus-5-5");
  });

  test("Tab after typing takes the highlighted match", () => {
    const box = open();
    type(box, "gpt-5.5");
    key(box, "Tab");
    expect(picked()).toBe("gpt-5-5");
  });

  test("a model key that is not a model, like constructor, falls back to the default", () => {
    const box = open("?model=constructor");
    expect(picked()).toBe("claude-opus-5-5");
    expect(box.placeholder || box.value).toBe("Claude Opus 5.5");
  });

  test("an introductory price shows its end date in the list and under the picked model", () => {
    const box = open();
    type(box, "argon");
    expect(document.getElementById("calc-list")!.textContent).toContain(
      "introductory price until November 30, 2026",
    );
    expect(introNote().hidden).toBe(true);
    key(box, "Enter");
    expect(introNote().hidden).toBe(false);
    expect(introNote().textContent).toBe(
      "Introductory price until November 30, 2026",
    );
    type(box, "opus");
    key(box, "Enter");
    expect(introNote().hidden).toBe(true);
  });

  test("a shared link to an introductory model shows the end date on load", () => {
    open("?model=gemini-4-argon");
    expect(introNote().hidden).toBe(false);
    expect(introNote().textContent).toContain("November 30, 2026");
  });
});

describe("comparison tool picker", () => {
  const data = {
    models: Object.fromEntries(
      MODELS.map((m) => [
        m.slug,
        {
          n: m.name,
          by: "Lab",
          in: m.input,
          out: m.output,
          ctx: 128_000,
          p: 1,
          f: {},
        },
      ]),
    ),
    pairs: [],
    asOf: null,
  };
  const open = async (d: object = data) => {
